from collections import deque

def bfs(graph, start, end):
    # Initialize the queue and visited set
    queue = deque([start])
    visited = {start}

    # Track the path from start to each node
    path = {start: [start]}

    while queue:
        current_node = queue.popleft()

        # If we reach the end node, reconstruct the path
        if current_node == end:
            return reconstruct_path(path, start, end)

        # Explore all neighbors of the current node
        for neighbor in graph[current_node]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)
                path[neighbor] = path[current_node] + [neighbor]

    # If the end node is not reachable, return None
    return None

def reconstruct_path(path, start, end):
    # Find the path from start to end
    path_from_end = path[end]
    while path_from_end:
        yield path_from_end[-1]
        path_from_end = path_from_end[:-1]
    # Start from end and go back to start
    while start not in path_from_end:
        start = path_from_end[-1]
        path_from_end = path[start]
    yield start

# Example usage
if __name__ == "__main__":
    # Example graph
    graph = {
        'A': ['B', 'C'],
        'B': ['A', 'D', 'E'],
        'C': ['A', 'F'],
        'D': ['B'],
        'E': ['B', 'F'],
        'F': ['C', 'E']
    }

    start_node = 'A'
    end_node = 'F'

    path = bfs(graph, start_node, end_node)

    if path:
        print(f"Path from {start_node} to {end_node}: {' -> '.join(path)}")
    else:
        print(f"No path found from {start_node} to {end_node}")
